/**
 * A vertical sequence of dated events (`design/components/timeline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/timeline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { Each, Icon, claimSlot, scope, type IconRole } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/timeline.module.css'

export type TimelineTone = 'neutral' | 'accent' | 'info' | 'success' | 'warning' | 'danger'

export interface TimelineEvent {
  title: string
  time: string
  detail?: string
  icon?: IconRole
  tone?: TimelineTone
}

export interface TimelineProps {
  /**
   * Events in reading order; Timeline never sorts them.
   */
  events: TimelineEvent[]
  /**
   * The list's accessible name, such as "Ticket history" rather than "Timeline".
   */
  label: string
}

/** A vertical sequence of dated events. */
export default function Timeline(given: TimelineProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <>
        {props.events.length > 0 ? (
          <ol class={styles.root} aria-label={props.label} data-member="timeline">
            <Each of={props.events} by={(_event, at) => at} renew>
              {(event) => (
                <li
                  class={styles.event}
                  data-tone={
                    event.tone === undefined || event.tone === 'neutral' ? undefined : event.tone
                  }
                >
                  {/* marker */}
                  <span class={styles.marker} aria-hidden="true">
                    {/* mark */}
                    <span class={styles.mark} data-mark={event.icon === undefined ? 'dot' : 'icon'}>
                      {event.icon !== undefined ? <Icon name={event.icon} size="sm" /> : null}
                    </span>
                  </span>
                  {/* copy */}
                  <span class={styles.copy}>
                    {/* title */}
                    <span class={styles.title}>{event.title}</span>
                    {/* time */}
                    <span class={styles.time}>{event.time}</span>
                    {event.detail !== undefined ? (
                      <span class={styles.detail}>{event.detail}</span>
                    ) : null}
                  </span>
                </li>
              )}
            </Each>
          </ol>
        ) : null}
      </>
    )
  })
}
